import sys


def main():
    tok = sys.stdin.read().split()
    n, cap = int(tok[0]), int(tok[1])
    best = [0] * (cap + 1)
    for i in range(n):
        w, v = int(tok[2 + 2 * i]), int(tok[3 + 2 * i])
        for c in range(cap, w - 1, -1):
            if best[c - w] + v > best[c]:
                best[c] = best[c - w] + v
    print(best[cap])


main()

